using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class CathedralProgressChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var c=new CathedralState();for(int i=0;i<40;i++)c.Advance(.5f,.24f);Check(!c.Building,"Faith below new threshold started shrine");for(int i=0;i<39;i++)c.Advance(.5f,.31f);Check(!c.Building,"Shrine skipped sustained faith");c.Advance(.5f,.31f);Check(c.Building&&c.authorized==1,"Saved village faith did not qualify");c.timber=6;for(int i=0;i<119;i++)Check(!c.Build(1),"Shrine finished before 120 worker seconds");Check(c.Build(1)&&c.level==1,"Completed labor did not finish shrine");for(int i=0;i<40;i++)c.Advance(.5f,.31f);Check(!c.Building,"First threshold reduction unlocked higher stages");Check(JsonUtility.FromJson<CathedralState>(JsonUtility.ToJson(c)).Valid(),"Progress save invalid");Debug.Log("BWVR_CATHEDRAL_PROGRESS_MODEL_PASS: 25% shrine threshold, sustained qualification, 120 worker-seconds, higher thresholds and persistence");}
 public static void VerifyRuntime(Action<VillageCathedral,string> capture=null){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var temple=slice.GetComponentInChildren<VillageCathedral>();var god=slice.GetComponentInChildren<CreatureHybrid>();var world=slice.GetComponentInChildren<VillageResources>();var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};god.Interrupt("Cathedral progress QA");field.SetValue(slice,test);
  try{
   foreach(var person in slice.GetComponentsInChildren<VillagerSocial>()){person.ResetTask();person.GetComponent<VillagerExploration>().ResetTask();person.GetComponent<VillagerResourceGathering>().Cancel();person.GetComponent<VillagerBlockPlay>().ResetTask();person.Memory.faith=.31f;}
   world.ResetWorld();slice.GetComponentInChildren<VillageFamilies>().ResetWorld();temple.ResetWorld();for(int i=0;i<40;i++)temple.Advance(.5f);Check(test.Cathedral.authorized==1&&test.Cathedral.work==0,"31% village did not authorize naturally");
   var masonry=(GameObject[])typeof(VillageCathedral).GetField("masonry",F).GetValue(temple);var scaffold=(GameObject)typeof(VillageCathedral).GetField("scaffold",F).GetValue(temple);var models=(GameObject[])typeof(VillageCathedral).GetField("models",F).GetValue(temple);Check(!masonry[0].activeSelf&&!scaffold.activeSelf,"Unpaid building appeared");capture?.Invoke(temple,"foundation");test.Cathedral.timber=6;temple.Advance(.1f);Check(scaffold.activeSelf&&!masonry[0].activeSelf,"Timber delivery not represented");capture?.Invoke(temple,"supplied");
   float previousTop=float.NegativeInfinity;foreach(float fraction in new[]{.2f,.5f,.85f}){test.Cathedral.work=CathedralState.Labor[0]*fraction;temple.Advance(.1f);Check(masonry[0].activeSelf&&temple.ConstructionTop>previousTop&&Mathf.Abs(temple.VisibleConstructionFraction-fraction)<.001f,"Masonry did not follow actual labor");previousTop=temple.ConstructionTop;Check(masonry[0].GetComponentsInChildren<Collider>().All(c=>!c.enabled),"Partial facade changed collision");foreach(var renderer in masonry[0].GetComponentsInChildren<Renderer>()){Check(renderer.sharedMaterial.shader.name=="BWVR/CathedralConstruction","Partial masonry lost reveal shader");var p=new MaterialPropertyBlock();renderer.GetPropertyBlock(p);Check(Mathf.Abs(p.GetFloat("_BuildTop")-temple.ConstructionTop)<.00001f,"Reveal/shadow cutoff not assigned");}capture?.Invoke(temple,"work-"+Mathf.RoundToInt(fraction*100));}
   test.paused=true;float top=temple.ConstructionTop,work=test.Cathedral.work;temple.Advance(1);Check(top==temple.ConstructionTop&&work==test.Cathedral.work,"Paused construction moved");test.paused=false;
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);temple.ResetWorld();Check(Mathf.Abs(temple.VisibleConstructionFraction-.85f)<.001f&&masonry[0].activeSelf&&scaffold.activeSelf,"Native resume lost visible construction");
   test.Cathedral.work=CathedralState.Labor[0]-1;Check(test.Cathedral.Build(1),"Final paid work did not complete");temple.Advance(.1f);Check(models[0].activeSelf&&models[0].GetComponentsInChildren<Renderer>().All(r=>r.enabled)&&!masonry[0].activeSelf&&!scaffold.activeSelf,"Completion retained temporary art");capture?.Invoke(temple,"complete");
   for(int level=1;level<5;level++){test.Cathedral.level=level;test.Cathedral.authorized=level+1;test.Cathedral.timber=CathedralState.Timber[level];test.Cathedral.work=CathedralState.Labor[level]*.5f;temple.Advance(.1f);Check(masonry[level].activeSelf&&models[level-1].GetComponentsInChildren<Renderer>().All(r=>!r.enabled)&&test.Valid(),"Upgrade presentation or save invalid");capture?.Invoke(temple,"upgrade-"+level);}
   var shader=Resources.Load<Shader>("Cathedrals/Construction");Check(!UnityEditor.ShaderUtil.ShaderHasError(shader),"Construction shader has errors");Debug.Log("BWVR_CATHEDRAL_PROGRESS_RUNTIME_PASS: natural 31% qualification, supplied scaffolding, paid labor reveal/shadows, pause, native save/resume, all upgrades and completed facade cleanup");
  }finally{field.SetValue(slice,original);temple.ResetWorld();world.ResetWorld();slice.GetComponentInChildren<VillageFamilies>().ResetWorld();god.NewSeason();}
 }
}
}
